<div class="modal-backdrop" x-show="serverOpen" x-cloak><section class="domain-modal managed-create-modal managed-create-redesign" @click.outside="serverOpen=false"><div class="domain-modal-head"><div><span class="section-icon"><i data-lucide="cloud-cog"></i></span><div><h2>Create managed server</h2><p>Select a provider, plan, region, and operating system.</p></div></div><button @click="serverOpen=false"><i data-lucide="x"></i></button></div><form method="post" action="{{ route('managed.servers.store') }}">@csrf<div class="domain-modal-body"><label class="field"><span>Server name</span><input name="name" required placeholder="Production Cloud 01"></label><div class="managed-provider-cards"><template x-for="connection in connections" :key="connection.id"><button type="button" :class="selectedConnection==connection.id&&'is-selected'" @click="selectConnection(connection)"><span x-text="connection.provider==='digitalocean'?'DO':'HZ'"></span><div><strong x-text="connection.provider==='digitalocean'?'DigitalOcean':'Hetzner Cloud'"></strong><small>Verified platform provider</small></div><i data-lucide="circle-check"></i></button></template></div><input type="hidden" name="provider_connection_id" :value="selectedConnection"><label class="field"><span>Server plan</span><select name="managed_server_plan_id" x-model="selectedPlan" @change="syncPlan()" required><option value="">Choose compute plan</option><template x-for="plan in filteredPlans" :key="plan.id"><option :value="plan.id" x-text="`${plan.name} · ${money(plan.monthly_price)}/month`"></option></template></select></label><div class="form-grid form-grid--two"><label class="field"><span>Region</span><select name="region" x-model="region" required><template x-for="item in regions"><option :value="item" x-text="item.toUpperCase()"></option></template></select></label><label class="field"><span>Operating system</span><select name="image" x-model="image" required><template x-for="item in images"><option :value="item" x-text="formatImage(item)"></option></template></select></label></div><div class="managed-price-summary" x-show="currentPlan"><span><small>Monthly managed server</small><strong x-text="currentPlan?money(currentPlan.monthly_price):'$0.00'"></strong></span><p>Includes infrastructure, provisioning, monitoring, and platform management.</p></div></div><div class="domain-modal-actions"><button type="button" class="button button--secondary" @click="serverOpen=false">Cancel</button><button class="button button--primary" :disabled="!selectedConnection||!selectedPlan"><i data-lucide="rocket"></i>Create & provision</button></div></form></section></div>
</div><script>function managedCatalog(connections,plans,open){return{connections,plans,serverOpen:open,selectedConnection:'',provider:'',selectedPlan:'',region:'',image:'',regions:[],images:[],get filteredPlans(){return this.plans.filter(p=>p.provider===this.provider)},get currentPlan(){return this.plans.find(p=>String(p.id)===String(this.selectedPlan))},init(){if(this.connections[0])this.selectConnection(this.connections[0])},selectConnection(c){this.selectedConnection=c.id;this.provider=c.provider;this.selectedPlan='';this.syncPlan()},choosePlan(id){const p=this.plans.find(x=>String(x.id)===String(id)),c=this.connections.find(x=>x.provider===p.provider);if(c)this.selectConnection(c);this.selectedPlan=String(id);this.syncPlan();this.serverOpen=true},syncPlan(){const p=this.currentPlan;this.regions=p?.regions||[];this.images=p?.images||[];this.region=this.regions[0]||'';this.image=this.images[0]||''},money(c){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100)},formatImage(v){return v.replaceAll('-',' ').replace('ubuntu','Ubuntu').replace('debian','Debian')}}}</script></x-dashboard-layout>
